59		void saveOwner(Owner owner) throws DataAccessException;
60		void deleteOwner(Owner owner) throws DataAccessException;
61	
62		/**
63		 * Returns {@code true} if any owner already uses the given telephone number. The argument and every
64		 * stored value are compared in their normalized (digits-only) form, so differently formatted but
65		 * equivalent numbers collide. Enforces the "unique telephone" invariant for every owner write path.
66		 *
67		 * @param telephone the telephone number to look for (in any format)
68		 * @return whether the normalized telephone is already in use by an owner
69		 */
70		boolean isTelephoneInUse(String telephone) throws DataAccessException;
