140	    public Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException {
141	        if (lastName != null) {
142	            return ownerRepository.findByLastName(lastName, pageable);
143	        }
144	        return ownerRepository.findAll(pageable);
