233	    @Override
234	    @Transactional(readOnly = true)
235	    public Collection<Vet> findVets() throws DataAccessException {
236	        return vetRepository.findAll();
237	    }
238	
239	    @Override
240	    @Transactional
241	    public void saveOwner(Owner owner) throws DataAccessException {
242	        if (owner.isNew()) {
243	            if (owner.getCustomerCode() == null) {
244	                owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
245	            }
246	            if (owner.getNamesakeCount() == null) {
247	                owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
248	            }
249	        }
250	        ownerRepository.save(owner);
251	
252	    }
253	
254	    /**
255	     * Count the existing owners (before this create) that share the given first and last name,
256	     * compared case-insensitively, as required by the read-only {@code namesakeCount} field.
257	     */
258	    private int countNamesakes(String firstName, String lastName) {
259	        if (firstName == null || lastName == null) {
260	            return 0;
261	        }
262	        return (int) ownerRepository.findAll().stream()
263	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
264	                && lastName.equalsIgnoreCase(owner.getLastName()))
265	            .count();
266	    }
267	
268	    /**
269	     * Build a customer code formatted {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3}
270	     * is the upper-cased first three letters of the owner's city, {@code LAST3} the
271	     * upper-cased first three letters of the owner's last name and {@code NNNN} a per-city,
272	     * 4-digit zero-padded sequence equal to one more than the current number of owners
273	     * already in that city (e.g. {@code 'LON-SMI-0007'}).
274	     */
275	    private String generateCustomerCode(String city, String lastName) {
276	        String cityName = city == null ? "" : city;
277	        String city3 = cityName.substring(0, Math.min(3, cityName.length())).toUpperCase();
278	        String name = lastName == null ? "" : lastName;
279	        String last3 = name.substring(0, Math.min(3, name.length())).toUpperCase();
280	        long sequence = countOwnersInCity(cityName) + 1L;
281	        return String.format("%s-%s-%04d", city3, last3, sequence);
282	    }
283	
284	    /**
285	     * Count the existing owners whose city matches the given city, compared case-insensitively,
286	     * used to derive the per-city sequence of the customer code.
287	     */
288	    private long countOwnersInCity(String city) {
289	        if (city == null) {
290	            return 0L;
291	        }
292	        return ownerRepository.findAll().stream()
293	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
294	            .count();
295	    }
296	
297	    @Override
298	    @Transactional(readOnly = true)
299	    public boolean isTelephoneInUse(String telephone) throws DataAccessException {
300	        String normalized = normalizeTelephone(telephone);
301	        if (normalized == null) {
302	            return false;
303	        }
304	        return ownerRepository.findAll().stream()
305	            .map(owner -> normalizeTelephone(owner.getTelephone()))
306	            .anyMatch(normalized::equals);
307	    }
308	
309	    @Override
310	    @Transactional(readOnly = true)
311	    public boolean isHouseholdInUse(String lastName, String address) throws DataAccessException {
312	        String normalizedLastName = normalizeHouseholdValue(lastName);
313	        String normalizedAddress = normalizeHouseholdAddress(address);
314	        if (normalizedLastName.isEmpty() || normalizedAddress.isEmpty()) {
315	            return false;
316	        }
317	        return ownerRepository.findAll().stream()
318	            .anyMatch(owner -> normalizedLastName.equals(normalizeHouseholdValue(owner.getLastName()))
319	                && normalizedAddress.equals(normalizeHouseholdAddress(owner.getAddress())));
320	    }
321	
322	    @Override
323	    @Transactional(readOnly = true)
324	    public String householdIdFor(String lastName, String address) throws DataAccessException {
325	        String key = normalizeHouseholdValue(lastName) + "\u0000" + normalizeHouseholdAddress(address);
326	        try {
327	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
328	            StringBuilder sb = new StringBuilder(32);
329	            for (int i = 0; i < 8; i++) {
330	                sb.append(String.format("%02X", digest[i]));
331	            }
332	            return sb.toString();
333	        } catch (NoSuchAlgorithmException ex) {
334	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
335	        }
336	    }
337	
338	    /**
339	     * Normalizes a household field (last name or address) for duplicate comparison by trimming,
340	     * collapsing runs of whitespace to a single space and lower-casing, so differently cased or
341	     * spaced but equivalent values compare equal.
342	     */
343	    private static String normalizeHouseholdValue(String value) {
344	        if (value == null) {
345	            return "";
346	        }
347	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
348	    }
349	
350	    /**
351	     * Normalizes an address for household comparison by first applying the canonical address
352	     * normalization (trim, collapse whitespace, upper-case and expand common abbreviations) and
353	     * then the shared household-value normalization, so every address comparison uses the same
354	     * normalized form regardless of how the value was originally supplied.
355	     */
356	    private static String normalizeHouseholdAddress(String address) {
357	        return normalizeHouseholdValue(AddressNormalizer.normalize(address));
358	    }
359	
360	    /**
361	     * Reduces a telephone number to its canonical E.164 form so that differently formatted but
362	     * equivalent numbers compare equal. A value already stored that cannot form valid E.164
363	     * (e.g. unusual legacy data) falls back to its digits-only form rather than failing lookup.
364	     */
365	    private static String normalizeTelephone(String telephone) {
366	        if (telephone == null) {
367	            return null;
368	        }
369	        try {
370	            return TelephoneNormalizer.toE164(telephone);
371	        } catch (InvalidTelephoneException ex) {
372	            return telephone.replaceAll("\\D", "");
373	        }
374	    }
375	
376	    @Override
377	    @Transactional(readOnly = true)
378	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
379	        return ownerRepository.findByLastName(lastName);
380	    }
381	
382	    @Override
383	    @Transactional(readOnly = true)
384	    public Collection<Visit> findVisitsByPetId(int petId) {
385	        return visitRepository.findByPetId(petId);
386	    }
387	
388	    @Override
389	    @Transactional(readOnly = true)
390	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
391	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
392	    }
393	
394	    private <T> T findEntityById(Supplier<T> supplier) {
395	        try {
396	            return supplier.get();
397	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
398	            // Just ignore not found exceptions for Jdbc/Jpa realization
399	            return null;
400	        }
401	    }
402	
403	}
